    variants = set()
    for reflected in (False, True):
        pts = [(r, -c if reflected else c) for r, c in seed]
        for _ in range(4):
            min_r = min(r for r, c in pts)
            min_c = min(c for r, c in pts)
            variants.add(tuple(sorted((r - min_r, c - min_c) for r, c in pts)))
            pts = [(c, -r) for r, c in pts]

    out = [row[:] for row in grid]
